/* SPDX-License-Identifier: GPL-2.0-or-later
 * Kelvin vertex programs on the GPU: D3D11 half (shader/layout objects, buffer rings, draw, stream-out verification).
 * The HLSL itself is generated by nv2a_kelvin.c from the NV2A program words (semantics follow xemu's vsh-prog.c, GPL-2.0+).
 *
 * c83: vertex shaders come from the persistent shader cache (d3d8_shcache.c) and, on a miss, compile on a worker thread while the
 * caller draws that one draw on the CPU path; vertex+index data share one large NO_OVERWRITE ring (one Map per draw) and the per-draw
 * constants live in a constant ring bound with VSSetConstantBuffers1 offsets (one Map per draw; the 192-row table only when it changed). */
#include "d3d8_internal.h"
#include "d3d8_kvp.h"
#include "d3d8_shcache.h"
#include <d3dcompiler.h>
#include <d3d11_1.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern void  d3d8_shaders_prepare_draw(DWORD handle);
extern BOOL  d3d8_combiners_prepare_draw(void);
extern int   d3d8_nv2a_psh_take_skip(void);
extern int   d3d8_cur_target_screen_sized(void);
extern float d3d8_screen_logical_w(void);
extern float d3d8_screen_logical_h(void);
extern float d3d8_xmap_s(void);
extern float d3d8_xmap_o(void);

#define KVP_FVF (D3DFVF_XYZRHW | D3DFVF_DIFFUSE | D3DFVF_SPECULAR | 0x500u | 0x02AA0000u)
#define KVP_VIB_BYTES (64u << 20)     /* vertex + index ring */
#define KVP_CBR_BYTES (8u << 20)      /* constant ring */
#define KVP_CONST_ROWS 192
#define KVP_CONST_BYTES (KVP_CONST_ROWS * 16u)
#define KVP_CB_ALIGN 256u
#define KVP_VS_FLAGS (D3DCOMPILE_IEEE_STRICTNESS | D3DCOMPILE_OPTIMIZATION_LEVEL3)

struct D3D8KvpProgram {
    char *hlsl;
    char name[48];
    uint32_t mask;
    int nattr;
    D3D11_INPUT_ELEMENT_DESC el[16];
    ID3D11VertexShader *vs;
    ID3D11InputLayout  *il;
    volatile LONG status;          /* 0 = compiling, 1 = ready, -1 = failed */
    ID3D11VertexShader *vs_v;      /* KVP_VERIFY variant (lazy, synchronous) */
    ID3D11GeometryShader *gs_v;    /* stream-out geometry shader built from vs_v */
    int verify_failed;
};

typedef struct {
    float screen[2], xscale, xoffset;
    float clip_max, fog_en;
    uint32_t fog_mode;
    float fog_p0, fog_p1, fog_p2;
    uint32_t dotraw;
    float pad0;
    float tscale[8];
} KvpDrawCB;

/* set by d3d8_shaders_prepare_draw (the fixed-function path rebinds the vertex stage and layout), so the cached bindings are re-issued */
int g_kvp_ff_dirty = 1;
static D3D8KvpProgram *g_bound_prog;
static int g_bound_topo = -1;
static long long g_perf[4]; static unsigned g_perf_n;   /* KVP_PERF=1: upload / prepare / bind+draw, microseconds per draw every 1000 draws */
static int g_perf_on = -1;
static long long qpc_now(void) { LARGE_INTEGER q; if (g_perf_on < 0) g_perf_on = getenv("KVP_PERF") != NULL; if (!g_perf_on) return 0; QueryPerformanceCounter(&q); return q.QuadPart; }

static ID3D11DeviceContext1 *g_ctx1;
static ID3D11Buffer *g_vib, *g_cbr;                 /* draw path rings */
static UINT g_vib_off, g_cbr_off;
static unsigned g_cbr_gen = 1;                      /* bumped when the constant ring wraps (old constant regions die) */
static float g_const_shadow[KVP_CONST_ROWS * 4];
static UINT g_const_off; static unsigned g_const_gen;   /* where the last uploaded 192-row table lives, and in which ring generation */
static ID3D11Buffer *g_cb_const, *g_cb_draw;        /* verify path (plain per-call buffers) */
static ID3D11Buffer *g_so_buf, *g_so_stage;
static UINT g_so_bytes;

static HRESULT make_buffer(ID3D11Buffer **out, UINT bytes, UINT bind)
{
    D3D11_BUFFER_DESC bd;
    memset(&bd, 0, sizeof(bd));
    bd.ByteWidth = bytes; bd.Usage = D3D11_USAGE_DYNAMIC; bd.BindFlags = bind; bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    return ID3D11Device_CreateBuffer(d3d8_GetD3D11Device(), &bd, NULL, out);
}

static int kvp_init(void)
{
    if (g_vib) return 1;
    if (FAILED(make_buffer(&g_cb_const, KVP_CONST_BYTES, D3D11_BIND_CONSTANT_BUFFER))) return 0;
    if (FAILED(make_buffer(&g_cb_draw, KVP_CB_ALIGN, D3D11_BIND_CONSTANT_BUFFER))) return 0;
    if (FAILED(make_buffer(&g_cbr, KVP_CBR_BYTES, D3D11_BIND_CONSTANT_BUFFER))) return 0;
    if (FAILED(make_buffer(&g_vib, KVP_VIB_BYTES, D3D11_BIND_VERTEX_BUFFER | D3D11_BIND_INDEX_BUFFER))) { g_vib = NULL; return 0; }
    if (FAILED(ID3D11DeviceContext_QueryInterface(d3d8_GetD3D11Context(), &IID_ID3D11DeviceContext1, (void **)&g_ctx1))) g_ctx1 = NULL;
    return 1;
}

static int compile_vs_sync(const char *hlsl, const char *name, int verify, ID3DBlob **blob)
{
    D3D_SHADER_MACRO defs[2] = { { "KVP_VERIFY", "1" }, { NULL, NULL } };
    ID3DBlob *err = NULL;
    HRESULT hr = D3DCompile(hlsl, strlen(hlsl), name, verify ? defs : NULL, NULL, "main", "vs_5_0", KVP_VS_FLAGS, 0, blob, &err);
    if (FAILED(hr)) {
        fprintf(stderr, "[KVP] compile of %s failed (hr=%08lX): %.600s\n", name, (unsigned long)hr,
                err ? (const char *)ID3D10Blob_GetBufferPointer(err) : "?");
        if (err) ID3D10Blob_Release(err);
        return 0;
    }
    if (err) ID3D10Blob_Release(err);
    return 1;
}

static void kvp_finish(D3D8KvpProgram *p, const void *code, size_t n)
{
    int ok = code != NULL;
    if (ok && (FAILED(ID3D11Device_CreateVertexShader(d3d8_GetD3D11Device(), code, n, NULL, &p->vs)) ||
               FAILED(ID3D11Device_CreateInputLayout(d3d8_GetD3D11Device(), p->el, (UINT)p->nattr, code, n, &p->il)))) {
        fprintf(stderr, "[KVP] shader/layout creation failed for %s\n", p->name);
        ok = 0;
    }
    MemoryBarrier();
    InterlockedExchange(&p->status, ok ? 1 : -1);
}

static void kvp_done(void *ctx, const void *code, size_t n) { kvp_finish((D3D8KvpProgram *)ctx, code, n); }

D3D8KvpProgram *d3d8_kvp_create(const char *hlsl, const char *name, uint32_t input_mask)
{
    D3D8KvpProgram *p;
    int n = 0;
    uint64_t key; size_t csz = 0; void *code;
    if (!d3d8_GetD3D11Device() || !kvp_init() || !g_ctx1 || !input_mask) return NULL;
    p = (D3D8KvpProgram *)calloc(1, sizeof(*p));
    if (!p) return NULL;
    p->hlsl = _strdup(hlsl);
    strncpy(p->name, name, sizeof(p->name) - 1);
    p->mask = input_mask;
    for (int a = 0; a < 16; ++a)
        if (input_mask & (1u << a)) {
            D3D11_INPUT_ELEMENT_DESC e = { "ATTR", (UINT)a, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, (UINT)n * 16, D3D11_INPUT_PER_VERTEX_DATA, 0 };
            p->el[n++] = e;
        }
    p->nattr = n;
    key = shc_key(hlsl, strlen(hlsl), "vs_5_0", KVP_VS_FLAGS);
    code = shc_load("vs", key, &csz);
    if (code) { kvp_finish(p, code, csz); shc_free(code); }
    else shc_compile_async("vs", hlsl, strlen(hlsl), name, "vs_5_0", KVP_VS_FLAGS, key, kvp_done, p);
    return p;
}

int d3d8_kvp_status(D3D8KvpProgram *p) { return p ? (int)p->status : -1; }

/* Write up to two blobs back to back in one Map (second aligned to a2). force_discard: reset to the ring start with DISCARD. Returns 0 if it cannot fit. */
static int ring_put2(ID3D11Buffer *buf, UINT total, UINT *off, int force_discard, const void *d1, UINT n1, UINT a1, const void *d2, UINT n2, UINT a2, UINT *at1, UINT *at2, int *wrapped)
{
    D3D11_MAPPED_SUBRESOURCE m;
    D3D11_MAP mt = D3D11_MAP_WRITE_NO_OVERWRITE;
    UINT base = force_discard ? 0 : *off, o1 = (base + a1 - 1) / a1 * a1, o2, end;
    ID3D11DeviceContext *ctx = d3d8_GetD3D11Context();
    *wrapped = 0;
    o2 = (o1 + n1 + a2 - 1) / a2 * a2; end = o2 + n2;
    if (force_discard) { mt = D3D11_MAP_WRITE_DISCARD; *wrapped = 1; }
    else if (end > total) {
        o1 = 0; o2 = (n1 + a2 - 1) / a2 * a2; end = o2 + n2;
        if (end > total) return 0;
        mt = D3D11_MAP_WRITE_DISCARD; *wrapped = 1;
    }
    if (FAILED(ID3D11DeviceContext_Map(ctx, (ID3D11Resource *)buf, 0, mt, 0, &m))) return 0;
    memcpy((BYTE *)m.pData + o1, d1, n1);
    if (n2) memcpy((BYTE *)m.pData + o2, d2, n2);
    ID3D11DeviceContext_Unmap(ctx, (ID3D11Resource *)buf, 0);
    *at1 = o1; *at2 = o2; *off = end;
    return 1;
}

static void fill_draw_cb(KvpDrawCB *cb, const D3D8KvpDraw *d)
{
    memset(cb, 0, sizeof(*cb));
    cb->screen[0] = d3d8_screen_logical_w();
    cb->screen[1] = d3d8_screen_logical_h();
    cb->xscale = 1.0f; cb->xoffset = 0.0f;
    if (d3d8_cur_target_screen_sized()) { cb->xscale = d3d8_xmap_s(); cb->xoffset = d3d8_xmap_o(); }
    cb->clip_max = d->clip_max; cb->fog_en = d->fog_en; cb->fog_mode = d->fog_mode;
    cb->fog_p0 = d->fog_p[0]; cb->fog_p1 = d->fog_p[1]; cb->fog_p2 = d->fog_p[2];
    cb->dotraw = d->dotraw;
    memcpy(cb->tscale, d->tscale, sizeof(cb->tscale));
}

static D3D11_PRIMITIVE_TOPOLOGY topo_of(int t)
{
    switch (t) {
    case KVP_TOPO_POINTS:    return D3D11_PRIMITIVE_TOPOLOGY_POINTLIST;
    case KVP_TOPO_LINES:     return D3D11_PRIMITIVE_TOPOLOGY_LINELIST;
    case KVP_TOPO_LINESTRIP: return D3D11_PRIMITIVE_TOPOLOGY_LINESTRIP;
    case KVP_TOPO_TRISTRIP:  return D3D11_PRIMITIVE_TOPOLOGY_TRIANGLESTRIP;
    default:                 return D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST;
    }
}

/* returns 1 drawn, 2 skipped on purpose (the pixel shader is still compiling), 0 = caller must use the CPU path */
extern int g_d3d8_cullprobe_req; extern void d3d8_cullprobe_draw(UINT vertex_count, int indexed);   /* c145 probe, see d3d8_device.c */
int d3d8_kvp_draw(D3D8KvpProgram *p, const D3D8KvpDraw *d)
{
    ID3D11DeviceContext *ctx = d3d8_GetD3D11Context();
    UINT stride, vb_at, ib_at = 0;
    long long t0, t1, t2;
    int wrapped;
    BYTE blk[KVP_CB_ALIGN];
    UINT cb_at, tab_at = 0, need_tab, force = 0;
    if (!p || !ctx || !kvp_init() || !g_ctx1 || p->status != 1) return 0;
    t0 = qpc_now();
    stride = (UINT)p->nattr * 16u;
    /* vertex + index data: one Map */
    if (!ring_put2(g_vib, KVP_VIB_BYTES, &g_vib_off, 0, d->verts, d->nverts * stride, stride, d->indices, d->indices ? d->nidx * 4u : 0, 4, &vb_at, &ib_at, &wrapped)) return 0;
    /* per-draw constants (+ the 192-row table when it changed) in the constant ring: one Map */
    {
        KvpDrawCB cb;
        BYTE big[KVP_CB_ALIGN + KVP_CONST_BYTES];
        UINT need_bytes;
        fill_draw_cb(&cb, d);
        memset(blk, 0, sizeof(blk));
        memcpy(blk, &cb, sizeof(cb));
        need_tab = !(g_const_gen == g_cbr_gen && !memcmp(g_const_shadow, d->constants, sizeof(g_const_shadow)));
        need_bytes = KVP_CB_ALIGN + (need_tab ? KVP_CONST_BYTES : 0);
        if (((g_cbr_off + KVP_CB_ALIGN - 1) / KVP_CB_ALIGN * KVP_CB_ALIGN) + need_bytes > KVP_CBR_BYTES) { force = 1; g_cbr_gen++; need_tab = 1; }
        if (need_tab) { memcpy(big, blk, KVP_CB_ALIGN); memcpy(big + KVP_CB_ALIGN, d->constants, KVP_CONST_BYTES); }
        if (!ring_put2(g_cbr, KVP_CBR_BYTES, &g_cbr_off, force, need_tab ? (const void *)big : (const void *)blk, KVP_CB_ALIGN + (need_tab ? KVP_CONST_BYTES : 0), KVP_CB_ALIGN, NULL, 0, 4, &cb_at, &tab_at, &wrapped)) return 0;
        if (need_tab) { g_const_off = cb_at + KVP_CB_ALIGN; g_const_gen = g_cbr_gen; memcpy(g_const_shadow, d->constants, sizeof(g_const_shadow)); }
    }
    t1 = qpc_now();

    /* combiner pixel stage (the nv2a pixel shader) + render states; the fixed-function stages only when the combiner path declines */
    if (!d3d8_combiners_prepare_draw()) {
        if (d3d8_nv2a_psh_take_skip()) return 2;   /* shader still compiling: skip this draw rather than draw it wrong */
        d3d8_shaders_prepare_draw(KVP_FVF);
        d3d8_combiners_prepare_draw();
    }
    d3d8_states_apply();
    t2 = qpc_now();

    if (g_kvp_ff_dirty || g_bound_prog != p) {
        ID3D11DeviceContext_IASetInputLayout(ctx, p->il);
        ID3D11DeviceContext_VSSetShader(ctx, p->vs, NULL, 0);
        g_bound_prog = p;
    }
    if (g_kvp_ff_dirty) { g_bound_topo = -1; g_kvp_ff_dirty = 0; }
    {
        ID3D11Buffer *bufs[2]; UINT first[2], num[2];
        bufs[0] = g_cbr; bufs[1] = g_cbr;
        first[0] = g_const_off / 16u; num[0] = KVP_CONST_BYTES / 16u;
        first[1] = cb_at / 16u;       num[1] = KVP_CB_ALIGN / 16u;
        ID3D11DeviceContext1_VSSetConstantBuffers1(g_ctx1, 4, 2, bufs, first, num);
    }
    ID3D11DeviceContext_IASetVertexBuffers(ctx, 0, 1, &g_vib, &stride, &vb_at);
    if (g_bound_topo != d->topo) { ID3D11DeviceContext_IASetPrimitiveTopology(ctx, topo_of(d->topo)); g_bound_topo = d->topo; }
    if (d->indices) {
        ID3D11DeviceContext_IASetIndexBuffer(ctx, g_vib, DXGI_FORMAT_R32_UINT, ib_at);
        if (g_d3d8_cullprobe_req) { g_d3d8_cullprobe_req = 0; d3d8_cullprobe_draw(d->nidx, 1); } else   /* c145 probe */
        ID3D11DeviceContext_DrawIndexed(ctx, d->nidx, 0, 0);
    } else {
        if (g_d3d8_cullprobe_req) { g_d3d8_cullprobe_req = 0; d3d8_cullprobe_draw(d->nverts, 0); } else   /* c145 probe */
        ID3D11DeviceContext_Draw(ctx, d->nverts, 0);
    }
    { extern void d3d8_gpubusy_mark(void); d3d8_gpubusy_mark(); }   /* c178 */
    {
        long long t3 = qpc_now();
        g_perf[0] += t1 - t0; g_perf[1] += t2 - t1; g_perf[2] += t3 - t2;
        if (++g_perf_n >= 1000) {
            if (g_perf_on > 0) { LARGE_INTEGER f; QueryPerformanceFrequency(&f);
                fprintf(stderr, "[KVP-PERF] per draw us: upload=%.2f prepare(psh+states)=%.2f bind+draw=%.2f\n",
                        g_perf[0] * 1e6 / (double)f.QuadPart / g_perf_n, g_perf[1] * 1e6 / (double)f.QuadPart / g_perf_n, g_perf[2] * 1e6 / (double)f.QuadPart / g_perf_n); }
            memset(g_perf, 0, sizeof(g_perf)); g_perf_n = 0;
        }
    }
    return 1;
}

int d3d8_kvp_verify(D3D8KvpProgram *p, const D3D8KvpDraw *d, float *out)
{
    ID3D11Device *dev = d3d8_GetD3D11Device();
    ID3D11DeviceContext *ctx = d3d8_GetD3D11Context();
    UINT stride, vb_at, dummy, need, so_off = 0;
    int wr;
    ID3D11Buffer *cbs[2];
    D3D11_MAPPED_SUBRESOURCE m;
    KvpDrawCB cb;
    BYTE blk[KVP_CB_ALIGN];
    if (!p || !dev || !ctx || !kvp_init() || p->verify_failed || p->status != 1) return 0;
    if (!p->gs_v) {
        ID3DBlob *blob = NULL;
        D3D11_SO_DECLARATION_ENTRY e[8];
        UINT strides[1] = { KVP_VERIFY_FLOATS * 4 };
        for (int i = 0; i < 8; ++i) {
            D3D11_SO_DECLARATION_ENTRY x = { 0, "TEXCOORD", (UINT)i, 0, (BYTE)(i == 7 ? 1 : 4), 0 };
            e[i] = x;
        }
        if (!compile_vs_sync(p->hlsl, p->name, 1, &blob) ||
            FAILED(ID3D11Device_CreateVertexShader(dev, ID3D10Blob_GetBufferPointer(blob), ID3D10Blob_GetBufferSize(blob), NULL, &p->vs_v)) ||
            FAILED(ID3D11Device_CreateGeometryShaderWithStreamOutput(dev, ID3D10Blob_GetBufferPointer(blob), ID3D10Blob_GetBufferSize(blob),
                                                                       e, 8, strides, 1, D3D11_SO_NO_RASTERIZED_STREAM, NULL, &p->gs_v))) {
            fprintf(stderr, "[KVP] verify shader setup failed for %s\n", p->name);
            if (blob) ID3D10Blob_Release(blob);
            p->verify_failed = 1;
            return 0;
        }
        ID3D10Blob_Release(blob);
    }
    need = d->nverts * KVP_VERIFY_FLOATS * 4u;
    if (need > g_so_bytes) {
        D3D11_BUFFER_DESC bd;
        if (g_so_buf) { ID3D11Buffer_Release(g_so_buf); g_so_buf = NULL; }
        if (g_so_stage) { ID3D11Buffer_Release(g_so_stage); g_so_stage = NULL; }
        memset(&bd, 0, sizeof(bd));
        bd.ByteWidth = need; bd.Usage = D3D11_USAGE_DEFAULT; bd.BindFlags = D3D11_BIND_STREAM_OUTPUT;
        if (FAILED(ID3D11Device_CreateBuffer(dev, &bd, NULL, &g_so_buf))) return 0;
        bd.Usage = D3D11_USAGE_STAGING; bd.BindFlags = 0; bd.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
        if (FAILED(ID3D11Device_CreateBuffer(dev, &bd, NULL, &g_so_stage))) return 0;
        g_so_bytes = need;
    }
    stride = (UINT)p->nattr * 16u;
    if (!ring_put2(g_vib, KVP_VIB_BYTES, &g_vib_off, 0, d->verts, d->nverts * stride, stride, NULL, 0, 4, &vb_at, &dummy, &wr)) return 0;
    /* plain per-call constant buffers */
    if (FAILED(ID3D11DeviceContext_Map(ctx, (ID3D11Resource *)g_cb_const, 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) return 0;
    memcpy(m.pData, d->constants, KVP_CONST_BYTES);
    ID3D11DeviceContext_Unmap(ctx, (ID3D11Resource *)g_cb_const, 0);
    fill_draw_cb(&cb, d);
    memset(blk, 0, sizeof(blk)); memcpy(blk, &cb, sizeof(cb));
    if (FAILED(ID3D11DeviceContext_Map(ctx, (ID3D11Resource *)g_cb_draw, 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) return 0;
    memcpy(m.pData, blk, KVP_CB_ALIGN);
    ID3D11DeviceContext_Unmap(ctx, (ID3D11Resource *)g_cb_draw, 0);

    ID3D11DeviceContext_IASetInputLayout(ctx, p->il);
    ID3D11DeviceContext_VSSetShader(ctx, p->vs_v, NULL, 0);
    ID3D11DeviceContext_GSSetShader(ctx, p->gs_v, NULL, 0);
    cbs[0] = g_cb_const; cbs[1] = g_cb_draw;
    ID3D11DeviceContext_VSSetConstantBuffers(ctx, 4, 2, cbs);
    ID3D11DeviceContext_IASetVertexBuffers(ctx, 0, 1, &g_vib, &stride, &vb_at);
    ID3D11DeviceContext_IASetPrimitiveTopology(ctx, D3D11_PRIMITIVE_TOPOLOGY_POINTLIST);
    ID3D11DeviceContext_SOSetTargets(ctx, 1, &g_so_buf, &so_off);
    ID3D11DeviceContext_Draw(ctx, d->nverts, 0);
    {   ID3D11Buffer *nullb = NULL; UINT z = 0;
        ID3D11DeviceContext_SOSetTargets(ctx, 1, &nullb, &z);
        ID3D11DeviceContext_GSSetShader(ctx, NULL, NULL, 0);
    }
    g_kvp_ff_dirty = 1;
    ID3D11DeviceContext_CopyResource(ctx, (ID3D11Resource *)g_so_stage, (ID3D11Resource *)g_so_buf);
    if (FAILED(ID3D11DeviceContext_Map(ctx, (ID3D11Resource *)g_so_stage, 0, D3D11_MAP_READ, 0, &m))) return 0;
    memcpy(out, m.pData, need);
    ID3D11DeviceContext_Unmap(ctx, (ID3D11Resource *)g_so_stage, 0);
    return 1;
}